#pragma once

#include <cstddef>

// HTML's named character references, every one the HTML standard defines, by
// which the SURBL test and the sender lists' URL entries read an HTML part's
// links as a browser does (SURBL.cpp). HtmlReferencesData.cpp is GENERATED by
// build/generate-html-references.py from the standard's own list,
// whatwg/entities.json, which it holds to its SHA-256; edit the generator,
// never that file.

namespace HM
{
   namespace HtmlReferences
   {
      // A reference's name without its '&' - "amp;", and for one HTML also
      // reads without its ';', "amp" as well - and the code point it stands
      // for, with a second for the few that stand for two (second is 0 for the
      // others: no reference stands for U+0000).
      struct NamedReference
      {
         const char *name;
         unsigned int first;
         unsigned int second;
      };

      // Sorted by name, byte by byte (strcmp), for a binary search.
      extern const NamedReference Named[];
      extern const size_t NamedCount;

      // The length of the longest name, with its ';', and of the longest HTML
      // reads without one.
      extern const size_t LongestName;
      extern const size_t LongestLegacyName;
   }
}
